/* page4-flow-data.js — 把轮播图内联为 data:URI
   file:// 协议下 WebGL 无法把本地文件当纹理上传（跨域污染），
   换成 data:URI 后不再受该限制，液态透镜效果可正常工作。
   [opt2026-10-23] 底图重新压过一遍再内联，体积从 888KB 降到约 700KB。 */
window.__P4_FLOW_DATA = {
  'page4-flow-0.jpg': 'data:image/jpeg;base64,',
  'page4-flow-1.jpg': 'data:image/jpeg;base64,',
  'page4-flow-2.jpg': 'data:image/jpeg;base64,',
  'page4-flow-3.jpg': 'data:image/jpeg;base64,',
  'page4-flow-4.jpg': 'data:image/jpeg;base64,',
  'page4-flow-5.jpg': 'data:image/jpeg;base64,'
};
